CREATE TABLE `leads` (`id` INT NOT NULL AUTO_INCREMENT, `name` VARCHAR(120) NOT NULL, `work_email` VARCHAR(255) NOT NULL, `company` VARCHAR(150) NOT NULL, `job_title` VARCHAR(120) NULL, `country` VARCHAR(100) NULL, `phone` VARCHAR(40) NULL, `sap_environment` VARCHAR(30) NULL, `current_sap_system` VARCHAR(200) NULL, `required_services` VARCHAR(300) NULL, `project_stage` VARCHAR(30) NULL, `timeline` VARCHAR(30) NULL, `estimated_scope` VARCHAR(30) NULL, `message` LONGTEXT NULL, `website` VARCHAR(200) NULL, `source` VARCHAR(50) NOT NULL DEFAULT 'contact_page', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `leads_created_at_idx` (`created_at`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;